#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_N 100
#define INF 1000000000

int n;
int grid[MAX_N][MAX_N];
int add_cost, remove_cost;

// Hungarian algorithm for minimum cost assignment
int hungarian(int cost[MAX_N][MAX_N], int assignment[MAX_N]) {
    int u[MAX_N+1], v[MAX_N+1], p[MAX_N+1], way[MAX_N+1];
    int minv[MAX_N+1];
    int used[MAX_N+1];

    for (int i = 1; i <= n; i++) {
        p[0] = i;
        int j0 = 0;

        for (int j = 0; j <= n; j++) {
            minv[j] = INF;
            used[j] = 0;
        }

        do {
            used[j0] = 1;
            int i0 = p[j0];
            int delta = INF;
            int j1 = 0;

            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    int cur = cost[i0-1][j-1] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }

            for (int j = 0; j <= n; j++) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);

        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }

    for (int j = 1; j <= n; j++) {
        assignment[p[j]-1] = j-1;
    }

    return -v[0];
}

