    int cost[MAX_N][MAX_N];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                // If we keep it, cost is 0; if we remove it, cost is remove_cost
                // But we need to consider: we can either keep (cost 0) or remove (cost remove_cost) and add elsewhere
                // The assignment will decide which cells have circles
                cost[i][j] = remove_cost;  // Cost to remove if we don't assign here
            } else {
                cost[i][j] = add_cost;  // Cost to add if we assign here
            }
        }
    }

    int assignment[MAX_N];
    int min_cost = hungarian(cost, assignment);

    // Count operations
    int operations_count = 0;
    int ops[MAX_N][3]; // row, col, type (0=add, 1=remove)

    for (int i = 0; i < n; i++) {
        int j = assignment[i];
        if (grid[i][j] == 0) {
            ops[operations_count][0] = i + 1;
            ops[operations_count][1] = j + 1;
            ops[operations_count][2] = 0; // add
            operations_count++;
        } else if (grid[i][j] == 1) {
            // Check if this circle needs to be removed (it's in a wrong position)
            // Actually, if it's assigned here, we keep it. If not assigned, we remove it.
        }
    }

    // Find circles that need to be removed (not in assignment)
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                int should_keep = 0;
                for (int k = 0; k < n; k++) {
                    if (assignment[k] == j && k == i) {
                        should_keep = 1;
                        break;
                    }
                }
                if (!should_keep) {
                    ops[operations_count][0] = i + 1;
                    ops[operations_count][1] = j + 1;
                    ops[operations_count][2] = 1; // remove
                    operations_count++;
                }
            }
        }
    }

    printf("%d\n", min_cost);
    printf("%d\n", operations_count);
    for (int i = 0; i < operations_count; i++) {
        printf("%d %d %d\n", ops[i][0], ops[i][1], ops[i][2]);
    }

    return 0;
}

