#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef long long ll;

#define INF64 ((ll)4e18)

typedef struct {
    int to, rev, cap;
    ll cost;
} Edge;

typedef struct {
    Edge *data;
    int size, cap;
} Vec;

typedef struct {
    int r, c, t; /* t=1 add, t=0 remove */
} Op;

static void vec_init(Vec *v) {
    v->data = NULL;
    v->size = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, Edge e) {
    if (v->size == v->cap) {
        int ncap = (v->cap == 0 ? 4 : v->cap * 2);
        Edge *nd = (Edge*)realloc(v->data, sizeof(Edge) * ncap);
        if (!nd) exit(1);
        v->data = nd;
        v->cap = ncap;
    }
    v->data[v->size++] = e;
}

static void add_edge(Vec *g, int u, int v, int cap, ll cost) {
    Edge a = {v, g[v].size, cap, cost};
    Edge b = {u, g[u].size, 0, -cost};
    vec_push(&g[u], a);
    vec_push(&g[v], b);
}

static ll min_cost_flow(Vec *g, int N, int s, int t, int maxf) {
    ll *dist = (ll*)malloc(sizeof(ll) * N);
    int *pv = (int*)malloc(sizeof(int) * N);
    int *pe = (int*)malloc(sizeof(int) * N);
    int *inq = (int*)malloc(sizeof(int) * N);
    int *q = (int*)malloc(sizeof(int) * (N * 4 + 10));
    if (!dist || !pv || !pe || !inq || !q) exit(1);

    ll res = 0;
    int flow = 0;

    while (flow < maxf) {
        for (int i = 0; i < N; i++) {
            dist[i] = INF64;
            inq[i] = 0;
        }
        int head = 0, tail = 0;
        dist[s] = 0;
        q[tail++] = s;
        inq[s] = 1;

        while (head != tail) {
            int v = q[head++];
            if (head == N * 4 + 10) head = 0;
            inq[v] = 0;
            for (int i = 0; i < g[v].size; i++) {
                Edge *e = &g[v].data[i];
                if (e->cap <= 0) continue;
                if (dist[e->to] > dist[v] + e->cost) {
                    dist[e->to] = dist[v] + e->cost;
                    pv[e->to] = v;
                    pe[e->to] = i;
                    if (!inq[e->to]) {
                        q[tail++] = e->to;
                        if (tail == N * 4 + 10) tail = 0;
                        inq[e->to] = 1;
                    }
                }
            }
        }

        if (dist[t] == INF64) break;

        int addf = maxf - flow;
        for (int v = t; v != s; v = pv[v]) {
            Edge *e = &g[pv[v]].data[pe[v]];
            if (addf > e->cap) addf = e->cap;
        }

        flow += addf;
        res += dist[t] * addf;

        for (int v = t; v != s; v = pv[v]) {
            Edge *e = &g[pv[v]].data[pe[v]];
            e->cap -= addf;
            g[v].data[e->rev].cap += addf;
        }
    }

    free(dist);
    free(pv);
    free(pe);
    free(inq);
    free(q);

    if (flow < maxf) return INF64;
    return res;
}

