    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            ll w;
            if (s[i][j] == 'o' || s[i][j] == '1' || s[i][j] == 'O') {
                w = -remc[i][j];
            } else {
                w = addc[i][j];
            }
            add_edge(g, ROW + i, COL + j, 1, w);
        }
