                    ops[opcnt].t = 0;
                    opcnt++;
                }
            }
        }
    }

    printf("%lld\n", ans);
    printf("%d\n", opcnt);
    for (int i = 0; i < opcnt; i++) {
        printf("%d %d %s\n", ops[i].r, ops[i].c, ops[i].t ? "add" : "remove");
    }

