}

#include <bits/stdc++.h>
using namespace std;

class Hungarian {
public:
    int n;
    vector<vector<long long>> a;
    vector<long long> u, v;
    vector<int> p, way;

    Hungarian(int n) : n(n), a(n, vector<long long>(n)), 
                      u(n+1), v(n+1), p(n+1), way(n+1) {}

    long long solve() {
        for (int i = 1; i <= n; ++i) {
            p[0] = i;
            int j0 = 0;
            vector<long long> minv(n+1, LLONG_MAX);
            vector<char> used(n+1, false);

            do {
                used[j0] = true;
                int i0 = p[j0];
                long long delta = LLONG_MAX;
                int j1 = 0;

                for (int j = 1; j <= n; ++j) {
                    if (!used[j]) {
                        long long cur = a[i0-1][j-1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta) {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                }

                for (int j = 0; j <= n; ++j) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);

            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0);
        }

        return -v[0];
    }

    vector<int> getAssignment() {
        vector<int> ans(n);
        for (int j = 1; j <= n; ++j) {
            ans[p[j]-1] = j-1;
        }
        return ans;
    }
};

