/*
Min-cost transformation of an n x n 0/1 grid into a permutation matrix
(exactly one circle in each row and each column).

Model:
Choose final cells (i, p[i]) forming a perfect matching.
For each cell:
- if initial=0 and chosen => add cost a[i][j]
- if initial=1 and not chosen => remove cost b[i][j]
- if initial already equals chosen state => 0

Let base = sum of b[i][j] over all initial 1 cells (remove all existing circles).
Then choosing cell (i,j) in final matching changes cost by:
- if initial=1: keep it instead of removing => -b[i][j]
- if initial=0: add it => +a[i][j]

So total = base + sum chosen weight[i][j],
where weight = initial? -b : +a.
Thus we need minimum-weight perfect matching in bipartite graph rows-columns.

We solve via Hungarian algorithm for minimum cost assignment in O(n^3).

Then reconstruct operations:
- chosen final cells kept/added
- all other initial 1 cells removed
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class Operation {
        int r, c;
        char type; // '+' add, '-' remove
        Operation(int r, int c, char type) {
            this.r = r;
            this.c = c;
            this.type = type;
        }
    }

    // Hungarian algorithm for rectangular/min-cost assignment, here square n x n.
    // Returns assignment p where p[i] = assigned column for row i (0-indexed).
    static int[] hungarian(long[][] cost) {
        int n = cost.length;
        long[] u = new long[n + 1];
        long[] v = new long[n + 1];
        int[] p = new int[n + 1];
        int[] way = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            p[0] = i;
            long[] minv = new long[n + 1];
            boolean[] used = new boolean[n + 1];
            Arrays.fill(minv, Long.MAX_VALUE / 4);
            int j0 = 0;

            do {
                used[j0] = true;
                int i0 = p[j0];
                long delta = Long.MAX_VALUE / 4;
                int j1 = 0;
                for (int j = 1; j <= n; j++) {
                    if (!used[j]) {
                        long cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta) {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                }
                for (int j = 0; j <= n; j++) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);

            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        int[] ans = new int[n];
        for (int j = 1; j <= n; j++) {
            ans[p[j] - 1] = j - 1;
        }
        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        int[][] s = new int[n][n];
        for (int i = 0; i < n; i++) {
            String line = fs.next();
            if (line.length() == n) {
                for (int j = 0; j < n; j++) {
                    char ch = line.charAt(j);
                    s[i][j] = (ch == '1' || ch == 'o' || ch == 'O' || ch == '*') ? 1 : 0;
                }
            } else {
                s[i][0] = Integer.parseInt(line);
                for (int j = 1; j < n; j++) s[i][j] = fs.nextInt();
            }
        }

        long[][] add = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) add[i][j] = fs.nextLong();
        }

        long[][] rem = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) rem[i][j] = fs.nextLong();
        }

        long base = 0;
        long[][] w = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (s[i][j] == 1) {
                    base += rem[i][j];
                    w[i][j] = -rem[i][j];
                } else {
                    w[i][j] = add[i][j];
                }
            }
        }

        int[] match = hungarian(w);

        boolean[][] chosen = new boolean[n][n];
        long ansCost = base;
        for (int i = 0; i < n; i++) {
            chosen[i][match[i]] = true;
            ansCost += w[i][match[i]];
        }

        List<Operation> ops = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (chosen[i][j]) {
                    if (s[i][j] == 0) ops.add(new Operation(i + 1, j + 1, '+'));
                } else {
                    if (s[i][j] == 1) ops.add(new Operation(i + 1, j + 1, '-'));
                }
            }
        }

        StringBuilder out = new StringBuilder();
        out.append(ansCost).append('\n');
        out.append(ops.size()).append('\n');
        for (Operation op : ops) {
            out.append(op.r).append(' ').append(op.c).append(' ').append(op.type).append('\n');
        }
        System.out.print(out.toString());
    }
}
